<script setup>
import { onMounted, ref, computed } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { uploadListingMedia, withImageToken } from '../../api/tools/imageCropper.js';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
import WorkflowCatalogInput from './WorkflowCatalogInput.vue';
const emit=defineEmits(['saved']);
const records=ref([]),keyword=ref(''),busy=ref(false),editor=ref(false),current=ref(null),form=ref({}),brands=ref([]),identity=ref('');
const imageNode=computed(()=>({id:'material_images',type:'images',label:'参考图片',count:form.value.images?.length||1,slots:Array.from({length:form.value.images?.length||1},(_,i)=>`参考图 ${i+1}`)}));
async function load(){busy.value=true;try{records.value=await apiClient.get(`/api/product-workflows/materials?keyword=${encodeURIComponent(keyword.value)}`,{noCache:true});}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
function edit(record){current.value=record||null;form.value=record?structuredClone(record.payload):{name:'',brand:'',model:'',material:'',category:'',role:'style',notes:'',images:['']};identity.value=[form.value.brand,form.value.model].filter(Boolean).join(' ');editor.value=true;}
async function upload(file,index){busy.value=true;try{const result=await uploadListingMedia(file,{source_module:'product_workflow_material',role:form.value.role}),url=result.publishUrl||result.url||result.previewUrl;if(!url)throw new Error('图片上传未返回地址');form.value.images[index]=url;}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function save(){busy.value=true;try{const saved=await apiClient.post('/api/product-workflows/materials',{id:current.value?.id,revision:current.value?.revision,payload:form.value});editor.value=false;await load();emit('saved',saved);ElMessage.success('已保存企业生产资料');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function archive(record){try{await ElMessageBox.confirm('停用后不能用于新任务，历史任务保留资料快照。','停用生产资料',{confirmButtonText:'停用',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=true;try{await apiClient.post('/api/product-workflows/materials',{id:record.id,revision:record.revision,payload:{...record.payload,archived:true}});await load();emit('saved');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
onMounted(()=>{load();apiClient.get('/api/ai-variant-lab/vehicle-catalog').then(r=>brands.value=r.brands||[]).catch(()=>{});});
</script>
<template>
 <div v-loading="busy"><div class="material-toolbar"><el-input v-model="keyword" clearable placeholder="搜索资料名称、品牌、型号、材质或类型" @keyup.enter="load" @clear="load"/><el-button @click="load">搜索</el-button><el-button type="primary" @click="edit()">新增生产资料</el-button></div><p class="hint">保存适配模型、材质特写、礼盒或风格资料，供整套流程或单个节点重复引用。</p>
 <el-empty v-if="!records.length" description="还没有生产资料，点击新增保存图片或说明"/>
 <div class="material-cards"><article v-for="record in records" :key="record.id"><el-image v-if="record.payload.images.length" :src="withImageToken(record.payload.images[0])" :preview-src-list="record.payload.images.map(withImageToken)" preview-teleported fit="contain"/><div><strong>{{ record.name }}</strong><p>{{ [record.payload.brand,record.payload.model,record.payload.material,record.payload.category].filter(Boolean).join(' · ') }}</p><small>{{ record.payload.notes }}</small><div><el-button link type="primary" @click="edit(record)">编辑</el-button><el-button link type="danger" @click="archive(record)">停用</el-button></div></div></article></div>
 <el-dialog v-model="editor" append-to-body :title="current?'编辑生产资料':'新增生产资料'" width="680px" top="4vh" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" class="workflow-material-dialog"><el-form label-position="top" :disabled="busy"><el-form-item label="资料名称" required><el-input v-model="form.name" placeholder="例如：TENET T7 适配钥匙、黑色礼盒包装"/></el-form-item><el-form-item label="品牌 / 型号（选填）"><WorkflowCatalogInput v-model="identity" :brands="brands" :disabled="busy" @identity="Object.assign(form,$event)" @reload="apiClient.get('/api/ai-variant-lab/vehicle-catalog',{noCache:true}).then(r=>brands=r.brands||[])"/></el-form-item><div class="material-fields"><el-form-item label="材质（选填）"><el-input v-model="form.material" placeholder="只填写已确认的材质"/></el-form-item><el-form-item label="类型（选填）"><el-input v-model="form.category" placeholder="例如：适配钥匙、包装、材质"/></el-form-item></div><el-form-item label="参考用途"><el-select v-model="form.role"><el-option label="版式 / 风格参考" value="style"/><el-option label="适配对象参考" value="compatibility"/><el-option label="真实产品资料" value="product"/></el-select></el-form-item><el-form-item label="资料说明"><el-input v-model="form.notes" type="textarea" :rows="3" placeholder="填写这份资料的用途、已核实事实和使用限制"/></el-form-item><el-form-item label="参考图片（最多 8 张）"><WorkflowMaterialInput v-model="form.images" compact :node="imageNode" :disabled="busy" @upload="upload"/><el-button :disabled="busy||form.images.length>=8" @click="form.images.push('')">增加图片</el-button></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="editor=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存到企业资料</el-button></template></el-dialog></div>
</template>
<style scoped>
.material-toolbar{display:flex;gap:10px}.material-toolbar .el-input{max-width:460px}.hint{color:var(--el-text-color-secondary);font-size:13px;line-height:1.8}.material-cards{display:grid;gap:12px;max-height:55vh;overflow:auto}.material-cards article{display:flex;gap:16px;border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:16px}.material-cards .el-image{width:90px;height:120px;flex-shrink:0}.material-cards p,.material-cards small{color:var(--el-text-color-secondary);line-height:1.6}.material-cards small{display:block;margin-bottom:12px}.material-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.el-select{width:100%}
</style>
<style>.workflow-material-dialog .el-dialog__body{max-height:70vh;overflow:auto}</style>
